package br.com.marquesautodetail.api.auth;
import br.com.marquesautodetail.api.auth.dto.*;import br.com.marquesautodetail.api.empresa.*;import br.com.marquesautodetail.api.usuario.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.security.Principal;
@RestController @RequestMapping("/auth") public class AuthController{ private final AuthService service; private final UsuarioRepository usuarios; private final EmpresaRepository empresas; public AuthController(AuthService service,UsuarioRepository usuarios,EmpresaRepository empresas){this.service=service;this.usuarios=usuarios;this.empresas=empresas;} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){return service.login(r);} @PostMapping("/register/cliente") public AuthResponse cliente(@Valid @RequestBody RegisterRequest r){return service.cadastrarCliente(r);} @PostMapping("/register/empresa") public AuthResponse empresa(@Valid @RequestBody RegisterRequest r){return service.cadastrarEmpresa(r);} @GetMapping("/me") public AuthResponse me(Principal principal){Usuario u=usuarios.findByEmailIgnoreCase(principal.getName()).orElseThrow(); Long empresaId=empresas.findByUsuario(u).map(Empresa::getId).orElse(null); return new AuthResponse("",u.getId(),u.getNome(),u.getEmail(),u.getRole().name(),empresaId);} }
